CustomField.formula:
If(
and(
(NOW() - Latest_Discharge__r.Census_Date__c) * 24 < 48,
or(
 Count_of_Calls__c < 2,
Count_of_Calls__c = null)),
"1",
if(
(NOW() - Latest_Discharge__r.Census_Date__c) * 24 < 48,
"2",
if(
and(
today() - Latest_Discharge_Date__c < 15,
not(isblank(Latest_Discharge_Date__c))
),
"3",
"4"
)
)
)
